<main class="content"><section class="welcome teacher-welcome"><div><span class="eyebrow">ÁREA DOCENTE</span><h2>Hola, <?=e($user['first_name'])?>. Tu ruta de aprendizaje está lista.</h2><p>Asignatura: <b><?=e($user['subject']??'General')?></b></p></div><a class="button light" href="<?=url('/docente/perfil')?>">Actualizar mis datos</a></section><?php foreach([['Tests disponibles',$tests,$user['test_enabled'],'test'],['Tabuladores',$tabulators,$user['tabulator_enabled'],'tabulador']] as [$label,$items,$enabled,$type]):?><section class="module"><div class="section-title"><h2><?=$label?></h2><span><?=count($items)?> recursos</span></div><?php if(!$enabled):?><div class="empty">Este módulo aún no está habilitado en tu perfil.</div><?php elseif(!$items):?><div class="empty">No hay recursos publicados para tu asignatura.</div><?php else:?><div class="resource-cards"><?php foreach($items as $r):?><article><span><?=$type==='test'?'✓':'▦'?></span><small><?=e(strtoupper($type))?></small><h3><?=e($r['name'])?></h3><p><?=e($r['description'])?></p><?php if($r['file_path']):?><a href="<?=url('/docente/descargar?id='.$r['id'])?>">Descargar archivo ↓</a><?php endif;?> <?php if($r['external_link']):?><a href="<?=e($r['external_link'])?>" target="_blank">Abrir enlace →</a><?php endif;?></article><?php endforeach;?></div><?php endif;?></section><?php endforeach;?></main>
